    // Publications: publications, text with quotes.
    'publications.noPeerIsConnectedSo2': 'Aucun pair n’est connecté : « Récupérer auprès des pairs » ne peut donc pas récupérer le contenu manquant. Connectez-vous à l’un d’eux depuis {peers}.',
    'publications.thisIsACorrelationOf2': 'Il s’agit d’une mise en relation de faits enregistrés indépendamment, par anchorId explicite — pas d’un verdict. Voir « Historique des preuves d’ancrage Bitcoin » ci-dessus pour le détail complet, observation par observation, de ce même anchorId.',
    'publications.thisIsAReadOnly': 'Ceci est une consultation en lecture seule du fichier ci-dessus — cela ne change rien à l’Archive des observations affichée plus haut sur cette page. Utilisez « Importer une archive » ci-dessus si vous voulez que cette archive la remplace.',
    'publications.whatReplacingTheCurrentArchive': 'Ce que changerait le remplacement de l’archive actuelle par l’archive externe ci-dessus — l’archive actuelle reste exactement telle quelle tant que « Remplacer l’archive actuelle » ci-dessous n’est pas cliqué explicitement.',
    'publications.replacingRestampsEveryFactIn': 'Le remplacement marque chaque fait de l’archive externe ci-dessus comme IMPORTÉ (0.8.83) — l’empreinte actuelle qui en résulte sera donc différente de « Empreinte externe » affichée ci-dessus, même si les observations sous-jacentes sont identiques.',
    'publications.localFactsWereObservedBy': 'Les faits locaux ont été observés directement par cette réplique. Les faits importés sont entrés dans cette archive par un import antérieur avec « Remplacer l’archive actuelle ». Aucun n’est plus digne de confiance que l’autre — cela indique seulement d’où vient chaque fait.',
    'publications.anExplicitDurableRecordThat2': 'Un enregistrement explicite et durable qu’une publication en référence une autre — jamais déduit de contenus, d’horodatages ou d’auteurs identiques. Les deux publications doivent déjà avoir une identité durable ci-dessus ; une référence n’est jamais une classification de « fork », seulement un fait simple et attribuable : cette publication désigne celle-là.',
    'publications.nothingHereIsSavedAnywhere': 'Rien ici n’est enregistré nulle part. Cette configuration n’existe que dans la mémoire de cette page pour cette session de navigation, et disparaît dès que la page est rechargée ou que « Effacer la configuration » est cliqué.',
    'publications.thisReplicaDoesNotCurrently': 'Cette réplique ne possède pas actuellement de snapshot valide. Choisissez une source ci-dessous — « Importer un Snapshot », « Matérialiser le Snapshot » d’un placement ou « Obtenir le Snapshot d’un pair » — pour réessayer.',

    // Publications: leaderboardHubView, text with quotes.
    'leaderboardHubView.aBadgePresentationOfThe': 'Une présentation sous forme de badges des succès que cet éditeur a déjà obtenus, sur toutes les publications qu’il a explicitement revendiquées — jamais un nouveau succès, et jamais un score, un rang ni une entrée de classement. Certains succès (ceux qui découlent des références) n’ont pas encore de badge et n’apparaissent que dans la carte « Profil de succès de l’éditeur » ci-dessus.',

    // Publications: publisherLeaderboardSnapshotClaimAuthoringView, text with quotes.
    'publisherLeaderboardSnapshotClaimAuthoringView.authorAndExportASigned': 'Créez et exportez une déclaration signée sur l’instantané de classement actuel de VOTRE PROPRE réplique — exactement la preuve que le champ « Preuve du pair » de l’Espace de réconciliation demande à un pair de coller. Générer, signer et exporter sont trois actions distinctes et explicites ; rien sur cette page ne s’exécute automatiquement.',
    'publisherLeaderboardSnapshotClaimAuthoringView.pasteThisIntoAPeer': 'Collez ceci dans le champ « Preuve du pair » de l’Espace de réconciliation d’un pair, ou envoyez-lui le fichier téléchargé.',

    // Publications: reconciliationCandidateLeaderboardView, text with quotes.
    'reconciliationCandidateLeaderboardView.noPeerArchiveSuppliedYet': 'Aucune archive de pair fournie pour l’instant — chaque décompte ci-dessous reste « Source uniquement » tant que vous n’en collez pas une. Collez l’archive exportée de la réplique d’un pair (Exporter l’archive, sur la page Publications) et cliquez sur « Utiliser comme archive du pair ».',

    // Publications: reconciliationWorkspaceView, text with quotes.
    'reconciliationWorkspaceView.reconcileThisReplicaSOwn': 'Réconciliez explicitement l’archive locale de cette réplique avec une preuve fournie par un pair. Rien sur cette page ne s’exécute automatiquement — la réconciliation n’a lieu que lorsque vous cliquez sur « Réconcilier » ci-dessous.',

